using System;
using Boki.Ending;
using Boki.Intro;
using UnityEditor;
using UnityEngine;
using Object = UnityEngine.Object;

namespace Boki.Editor
{
    // Imports the intro and ending ambience and cue clips and assigns them on the two cutscene prefabs, in place, so every
    // scene that already uses a prefab picks them up and keeps its overrides. Generated by music/generate_intro_ambience.py,
    // generate_intro_sfx.py, generate_ending_ambience.py and generate_ending_music.py.
    public static class CutsceneAmbienceSetup
    {
        private const string IntroPrefab = "Assets/Cutscenes/Intro/IntroCutscene.prefab";
        private const string EndingPrefab = "Assets/Cutscenes/Ending/EndingCutscene.prefab";
        private const string SfxFolder = "Assets/Audio/Sfx/";
        private const string IntroAmbience = SfxFolder + "intro_ambience.ogg";
        private const string EndingAmbience = SfxFolder + "ending_ambience.ogg";
        private const string EndingMusic = "Assets/Audio/Music/ending_music.ogg";
        private static readonly string[] IntroCues = { "intro_wake_up", "intro_arm_rustle", "intro_watch_check" };

        [MenuItem("Boki/Audio/Wire Intro And Ending Ambience")]
        public static void Wire()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode) throw new InvalidOperationException("Exit Play Mode first.");
            WirePrefab(IntroPrefab, root => AssignIntro(new SerializedObject(root.GetComponentInChildren<IntroCutscene>())));
            WirePrefab(EndingPrefab, root => AssignEnding(new SerializedObject(root.GetComponentInChildren<EndingCutscene>())));
            AssetDatabase.SaveAssets();
            Debug.Log("CUTSCENE_AMBIENCE_WIRED: intro and ending prefabs updated.");
        }

        public static void AssignIntro(SerializedObject so)
        {
            ConfigureBed(IntroAmbience);
            foreach (string cue in IntroCues) ConfigureCue(SfxFolder + cue + ".wav");
            Set(so, "ambience", Load<AudioClip>(IntroAmbience));
            Set(so, "wakeUp", Load<AudioClip>(SfxFolder + "intro_wake_up.wav"));
            Set(so, "armRustle", Load<AudioClip>(SfxFolder + "intro_arm_rustle.wav"));
            Set(so, "watchCheck", Load<AudioClip>(SfxFolder + "intro_watch_check.wav"));
            so.ApplyModifiedPropertiesWithoutUndo();
        }

        public static void AssignEnding(SerializedObject so)
        {
            ConfigureBed(EndingAmbience);
            ConfigureBed(EndingMusic);
            Set(so, "roomTone", Load<AudioClip>(EndingAmbience));
            Set(so, "reliefMusic", Load<AudioClip>(EndingMusic));
            so.ApplyModifiedPropertiesWithoutUndo();
        }

        private static void WirePrefab(string path, Action<GameObject> assign)
        {
            GameObject root = PrefabUtility.LoadPrefabContents(path);
            try
            {
                assign(root);
                PrefabUtility.SaveAsPrefabAsset(root, path);
            }
            finally
            {
                PrefabUtility.UnloadPrefabContents(root);
            }
        }

        // Short foley: decode once on load so playback has no streaming latency.
        private static void ConfigureCue(string path)
        {
            AudioImporter importer = Import(path);
            var settings = importer.defaultSampleSettings;
            settings.loadType = AudioClipLoadType.DecompressOnLoad;
            settings.compressionFormat = AudioCompressionFormat.PCM;
            settings.preloadAudioData = true;
            importer.defaultSampleSettings = settings;
            importer.forceToMono = true;
            importer.loadInBackground = false;
            importer.SaveAndReimport();
        }

        // Stereo beds of 10-25 s: kept as Vorbis in memory, decoded while playing.
        private static void ConfigureBed(string path)
        {
            AudioImporter importer = Import(path);
            var settings = importer.defaultSampleSettings;
            settings.loadType = AudioClipLoadType.CompressedInMemory;
            settings.compressionFormat = AudioCompressionFormat.Vorbis;
            settings.quality = 0.7f;
            settings.preloadAudioData = true;
            importer.defaultSampleSettings = settings;
            importer.forceToMono = false;
            importer.loadInBackground = false;
            importer.SaveAndReimport();
        }

        private static AudioImporter Import(string path)
        {
            AssetDatabase.ImportAsset(path);
            var importer = AssetImporter.GetAtPath(path) as AudioImporter;
            if (importer == null) throw new InvalidOperationException("Missing " + path + "; run the generator in music/.");
            return importer;
        }

        private static void Set(SerializedObject so, string field, Object value)
        {
            SerializedProperty property = so.FindProperty(field);
            if (property == null) throw new InvalidOperationException("Missing field " + field + " on " + so.targetObject.GetType().Name + ".");
            property.objectReferenceValue = value;
        }

        private static T Load<T>(string path) where T : Object
        {
            var asset = AssetDatabase.LoadAssetAtPath<T>(path);
            if (asset == null) throw new InvalidOperationException("Missing " + typeof(T).Name + " at " + path + ".");
            return asset;
        }
    }
}
